import { useEffect, useState, type FormEvent, type ReactNode } from 'react';
import { BrowserRouter, Link, NavLink, Navigate, Outlet, Route, Routes, useNavigate, useParams } from 'react-router-dom';
import { QueryClient, QueryClientProvider, useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { AuthProvider, useAuth } from './auth';
import { jsonBody, routes, type AppRulesResponse, type CatalogResponse, type Device, type FamilyDetail, type LocationCurrent, type Notification, type NotificationPage, type Sos, type UsageReport, type WebSettings, type ZonesResponse } from './api';
import { UiProvider, useUi } from './ui';
import type { Language } from './i18n';
import './style.css';

const queryClient = new QueryClient({ defaultOptions: { queries: { retry: 0, refetchOnWindowFocus: true, staleTime: 20_000 } } });
const dpath = (id: string, suffix: string) => `/v1/families/me/devices/${encodeURIComponent(id)}/${suffix}`;
const formatDate = (v?: string | null, lang: Language = 'fa') => v ? new Intl.DateTimeFormat(lang === 'fa' ? 'fa-IR' : 'en-GB', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(v)) : '—';
const localDateInput = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; };
const duration = (minutes: number, lang: Language) => lang === 'fa' ? `${Math.floor(minutes / 60)}س ${minutes % 60}د` : `${Math.floor(minutes / 60)}h ${minutes % 60}m`;
const getSosList = (value: unknown): Sos[] => Array.isArray(value) ? value as Sos[] : (value && typeof value === 'object' && 'sessions' in value && Array.isArray((value as { sessions: unknown }).sessions) ? (value as { sessions: Sos[] }).sessions : []);

function Icon({ name, size = 20 }: { name: string; size?: number }) {
  const paths: Record<string, ReactNode> = {
    grid: <><rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/></>,
    devices: <><rect x="5" y="2.5" width="14" height="19" rx="3"/><path d="M10 18h4"/></>,
    bell: <><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/></>,
    shield: <><path d="M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11Z"/><path d="m9 12 2 2 4-4"/></>,
    chart: <><path d="M3 3v18h18"/><path d="m7 14 4-4 4 3 6-7"/></>,
    settings: <><circle cx="12" cy="12" r="3"/><path d="m19.4 15 .1.1 1.4 1.1-1.4 2.4-1.7-.6a8 8 0 0 1-1.5.9l-.3 1.8h-2.8l-.3-1.8a8 8 0 0 1-1.5-.9l-1.7.6L6.3 16l1.4-1.1a8 8 0 0 1 0-1.8L6.3 12l1.4-2.4 1.7.6a8 8 0 0 1 1.5-.9l.3-1.8H14l.3 1.8a8 8 0 0 1 1.5.9l1.7-.6 1.4 2.4-1.4 1.1a8 8 0 0 1-.1 1.9Z"/></>,
    pin: <><path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/></>,
    clock: <><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></>,
    heart: <><path d="M20.8 8.6c0 5.4-8.8 11-8.8 11S3.2 14 3.2 8.6A4.6 4.6 0 0 1 12 6.3a4.6 4.6 0 0 1 8.8 2.3Z"/></>,
    menu: <><path d="M4 6h16M4 12h16M4 18h16"/></>,
    sun: <><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M2 12h2m16 0h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/></>,
    moon: <path d="M20.9 13A9 9 0 0 1 11 3.1 9 9 0 1 0 20.9 13Z"/>,
    arrow: <><path d="M7 17 17 7M7 7h10v10"/></>,
    lock: <><rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 1 1 8 0v3"/></>,
    eye: <><path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/></>,
    alert: <><path d="m10.3 3.8-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3.2l-8-14a2 2 0 0 0-3.4 0Z"/><path d="M12 9v4m0 4h.01"/></>,
  };
  return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name] ?? paths.grid}</svg>;
}

function useApi() {
  const auth = useAuth();
  return auth.request;
}
function useFamily() {
  const request = useApi();
  const family = useQuery({ queryKey: ['family'], queryFn: () => request<FamilyDetail>(routes.family) });
  const devices = useQuery({ queryKey: ['devices'], queryFn: () => request<Device[]>(routes.devices) });
  return { family, devices };
}
function Panel({ title, subtitle, children, action }: { title: string; subtitle?: string; children: ReactNode; action?: ReactNode }) {
  return <section className="panel"><div className="panel-head"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div>{action}</div>{children}</section>;
}
function LoadState({ error, onRetry }: { error?: Error | null; onRetry?: () => void }) {
  const { t } = useUi();
  return error ? <div className="state error-state" role="alert"><span className="state-icon"><Icon name="alert"/></span><div><strong>{t('error')}</strong><p>{error.message || t('backendOffline')}</p>{onRetry && <button className="btn btn-quiet" onClick={onRetry}>{t('retry')}</button>}</div></div> : <div className="state"><span className="spinner"/><span>{t('loading')}</span></div>;
}
function EmptyState({ children }: { children: ReactNode }) { return <div className="empty-state"><span className="empty-orb"><Icon name="grid" size={24}/></span><p>{children}</p></div>; }
function Pill({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'good' | 'warn' | 'bad' | 'neutral' }) { return <span className={`pill ${tone}`}>{children}</span>; }
function StatCard({ label, value, note, icon, accent = 'blue' }: { label: string; value: ReactNode; note: string; icon: string; accent?: string }) {
  return <article className={`stat-card accent-${accent}`}><div className="stat-top"><span>{label}</span><span className="stat-icon"><Icon name={icon}/></span></div><strong>{value}</strong><small>{note}</small></article>;
}

function AppRoot() {
  return <QueryClientProvider client={queryClient}><UiProvider><AuthProvider><BrowserRouter><AppRoutes/></BrowserRouter></AuthProvider></UiProvider></QueryClientProvider>;
}
function AppRoutes() {
  const { accessToken } = useAuth();
  const cache = useQueryClient();
  useEffect(() => { if (!accessToken) cache.clear(); }, [accessToken, cache]);
  return <Routes><Route path="/preview" element={<PreviewPage/>}/><Route path="/login" element={accessToken ? <Navigate to="/" replace/> : <LoginPage/>}/><Route element={accessToken ? <AppShell/> : <Navigate to="/login" replace/>}>
    <Route index element={<OverviewPage/>}/><Route path="/children" element={<DevicesPage/>}/>
    <Route path="/children/:deviceId" element={<NavigateToUsage/>}/>
    <Route path="/children/:deviceId/usage" element={<UsagePage/>}/><Route path="/children/:deviceId/location" element={<LocationPage/>}/><Route path="/children/:deviceId/zones" element={<ZonesPage/>}/><Route path="/children/:deviceId/apps" element={<RestrictionsPage/>}/><Route path="/children/:deviceId/web-safety" element={<WebSafetyPage/>}/>
    <Route path="/notifications" element={<NotificationsPage/>}/><Route path="/sos" element={<SosPage/>}/><Route path="/reports" element={<ReportsPage/>}/><Route path="/privacy" element={<PrivacyPage/>}/><Route path="/settings" element={<SettingsPage/>}/>
  </Route><Route path="*" element={<Navigate to={accessToken ? '/' : '/login'} replace/>}/></Routes>;
}

function LoginPage() {
  const { t, language, toggleLanguage } = useUi(); const { login, register } = useAuth(); const navigate = useNavigate();
  const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [mode, setMode] = useState<'login' | 'register'>('login'); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const health = useQuery({ queryKey: ['api-health'], queryFn: async () => { const r = await fetch('/health/ready', { cache: 'no-store', credentials: 'omit' }); if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.json() as Promise<{ status: string }> }, retry: 0, refetchInterval: 60_000 });
  const submit = async (e: FormEvent) => { e.preventDefault(); setError(''); setBusy(true); try { if (mode === 'login') await login(email.trim(), password); else await register(email.trim(), password); navigate('/'); } catch (e) { const err = e as Error & { status?: number; code?: string }; setError(err.status === 429 ? 'تلاش‌های ورود بیش از حد مجاز است؛ کمی بعد دوباره امتحان کنید.' : err.status === 401 ? 'ایمیل یا گذرواژه معتبر نیست.' : err.message || t('backendOffline')); } finally { setBusy(false); } };
  return <main className="auth-page"><div className="auth-orbit orbit-a"/><div className="auth-orbit orbit-b"/><header className="auth-top"><Brand/><div className="auth-actions"><span className={`connection-chip ${health.isError ? 'offline' : 'online'}`}><i/>{health.isError ? t('offline') : t('online')}</span><button className="icon-btn" aria-label={t('language')} onClick={toggleLanguage}>{language === 'fa' ? 'EN' : 'فا'}</button></div></header>
    <div className="auth-layout"><section className="auth-copy"><span className="eyebrow"><span className="eyebrow-dot"/> FAMILY CARE PLATFORM</span><h1>{language === 'fa' ? <>حضور، بدون<br/><em>نگرانی اضافه.</em></> : <>Stay connected,<br/><em>not overwhelmed.</em></>}</h1><p>{language === 'fa' ? 'وضعیت دستگاه‌های خانواده را با داده‌های واقعی، دسترسی روشن و احترام به حریم خصوصی دنبال کنید.' : 'Follow family device status with real data, clear controls, and respect for privacy.'}</p><div className="auth-trust"><span><Icon name="shield" size={18}/>{language === 'fa' ? 'حریم خصوصی در اولویت' : 'Privacy first'}</span><span><Icon name="lock" size={18}/>{language === 'fa' ? 'نشست امنِ حافظه‌ای' : 'Memory-only session'}</span></div></section>
      <section className="login-card"><div className="login-card-head"><div className="brand-mark"><Icon name="shield" size={26}/></div><div><h2>{mode === 'login' ? t('signIn') : t('register')}</h2><p>{t('sessionMemory')}</p></div></div>
        <form onSubmit={submit} className="login-form"><label>{t('email')}<input type="email" autoComplete="username" value={email} onChange={e => setEmail(e.target.value)} required maxLength={254} placeholder="parent@example.com" dir="ltr"/></label><label>{t('password')}<input type="password" autoComplete={mode === 'login' ? 'current-password' : 'new-password'} value={password} onChange={e => setPassword(e.target.value)} required minLength={mode === 'register' ? 12 : 1} maxLength={128} placeholder={language === 'fa' ? 'حداقل ۱۲ نویسه برای ساخت حساب' : 'At least 12 characters to register'} dir="ltr"/></label>
          {error && <p className="form-error" role="alert">{error}</p>}<button className="btn btn-primary btn-block" disabled={busy}>{busy ? t('loading') : mode === 'login' ? t('login') : t('register')}<span className="button-arrow">↗</span></button>
        </form><div className="login-foot"><span>{mode === 'login' ? (language === 'fa' ? 'حساب ندارید؟' : 'New to GuardianLink?') : (language === 'fa' ? 'از قبل حساب دارید؟' : 'Already have an account?')}</span><button className="text-button" onClick={() => { setMode(mode === 'login' ? 'register' : 'login'); setError(''); }}>{mode === 'login' ? t('register') : t('login')}</button></div>
        <div className="auth-note"><Icon name="lock" size={15}/><span>{t('signInAgain')}</span></div>
        <div className="preview-link-row"><span>{language === 'fa' ? 'فقط می‌خواهید ظاهر را ببینید؟' : 'Just want to inspect the interface?'}</span><Link to="/preview">{language === 'fa' ? 'پیش‌نمایش بدون داده' : 'Data-free preview'} ↗</Link></div>
      </section></div><footer className="auth-footer"><span>© GuardianLink</span><span>{t('privacyNote')}</span></footer></main>;
}

function PreviewPage() {
  const { language, toggleLanguage } = useUi(); const [active, setActive] = useState('overview');
  const fa = language === 'fa';
  const features = [
    { id: 'overview', icon: 'grid', title: fa ? 'نمای کلی' : 'Overview', desc: fa ? 'کارت‌های خانواده، دستگاه‌ها، اعلان‌ها و درخواست کمک؛ مقدارهای واقعی بعد از ورود از API می‌آیند.' : 'Family, device, notification and help-request cards; real values load from the API after sign-in.' },
    { id: 'devices', icon: 'devices', title: fa ? 'دستگاه‌های خانواده' : 'Family devices', desc: fa ? 'اتصال Child app با کد pairing و نمایش وضعیت deviceهای خانواده.' : 'Pair the Child app and view family device status.' },
    { id: 'usage', icon: 'clock', title: fa ? 'زمان صفحه' : 'Screen time', desc: fa ? 'گزارش امروز/هفته و تنظیم سقف؛ اجرا وابسته به وضعیت و قابلیت واقعی دستگاه است.' : 'Daily/weekly usage and limits; enforcement depends on actual device capability.' },
    { id: 'location', icon: 'pin', title: fa ? 'موقعیت و محدوده‌های امن' : 'Location & safe zones', desc: fa ? 'آخرین مختصات، دقت، timestamp و zoneهای server-backed؛ real-time نیست.' : 'Latest coordinates, accuracy, timestamp and server-backed zones; not real time.' },
    { id: 'apps', icon: 'shield', title: fa ? 'محدودیت اپ‌ها' : 'App restrictions', desc: fa ? 'قواعد و وضعیت enforcement گزارش‌شده از API.' : 'Rules and API-reported enforcement state.' },
    { id: 'web', icon: 'lock', title: 'Web Safety', desc: fa ? 'سیاست‌ها و رویدادهای بدون محتوای وب؛ URL بازدیدشده نمایش داده نمی‌شود.' : 'Policy and non-content events; visited URLs are not shown.' },
    { id: 'notifications', icon: 'bell', title: fa ? 'اعلان‌ها' : 'Notifications', desc: fa ? 'خواندن، تأیید و حل اعلان‌های API؛ push ادعا نمی‌شود.' : 'Read, acknowledge and resolve API alerts; no push is claimed.' },
    { id: 'sos', icon: 'heart', title: 'SOS', desc: fa ? 'وضعیت درخواست کمک و اقدام Parent؛ اورژانس تماس گرفته نمی‌شود.' : 'Help-request status and Parent actions; emergency services are not contacted.' },
    { id: 'reports', icon: 'chart', title: fa ? 'گزارش‌ها و حریم خصوصی' : 'Reports & privacy', desc: fa ? 'گزارش روزانهٔ مصرف؛ تماس‌ها، مخاطبان، دوربین و خروجی یکپارچه در API نیست.' : 'Daily usage report; calls, contacts, camera and combined export are not in the API.' },
  ];
  const selected = features.find(item => item.id === active) ?? features[0];
  return <div className="preview-page"><header className="preview-header"><Brand/><div className="preview-header-actions"><span className="preview-label"><Icon name="eye" size={15}/>{fa ? 'پیش‌نمایش ایستا · بدون نشست' : 'Static preview · no session'}</span><button className="language-btn" onClick={toggleLanguage}>{fa ? 'EN' : 'فا'}</button><Link className="btn btn-primary" to="/login">{fa ? 'ورود والد' : 'Parent sign in'}</Link></div></header><div className="preview-body"><aside className="preview-sidebar"><div className="side-label">{fa ? 'بخش‌ها' : 'SECTIONS'}</div>{features.map(item => <button key={item.id} className={`nav-item ${item.id === active ? 'selected' : ''}`} onClick={() => setActive(item.id)} aria-pressed={item.id === active}><Icon name={item.icon}/><span>{item.title}</span></button>)}</aside><main className="preview-content"><div className="preview-warning" role="status"><Icon name="lock"/><div><strong>{fa ? 'این فقط پیش‌نمایش رابط است' : 'Interface-only preview'}</strong><p>{fa ? 'هیچ حسابی وارد نشده، هیچ دادهٔ نمونه‌ای نمایش داده نمی‌شود و هیچ درخواست تغییردهنده‌ای ارسال نمی‌شود.' : 'No account is signed in, no sample data is shown, and no modifying request is sent.'}</p></div></div><PageHeading eyebrow={fa ? 'پیش‌نمایش' : 'PREVIEW'} title={selected.title} description={selected.desc}/>{active === 'overview' ? <><div className="stats-grid preview-stats">{[{icon:'heart',label:fa?'خانواده':'Family'},{icon:'devices',label:fa?'دستگاه‌های متصل':'Connected devices'},{icon:'bell',label:fa?'اعلان‌های خوانده‌نشده':'Unread notifications'},{icon:'alert',label:fa?'درخواست کمک فعال':'Active help requests'}].map(card => <StatCard key={card.label} label={card.label} value="—" note={fa?'پس از ورود، از API مشترک':'From the shared API after sign-in'} icon={card.icon}/>)}</div><div className="preview-feature-grid">{features.slice(1).map(item => <button className="preview-feature" key={item.id} onClick={() => setActive(item.id)}><span className="preview-feature-icon"><Icon name={item.icon}/></span><strong>{item.title}</strong><p>{item.desc}</p><span className="panel-link">{fa?'مشاهدهٔ ساختار':'View section'} <Icon name="arrow" size={14}/></span></button>)}</div></> : <Panel title={selected.title} subtitle={fa ? 'قابلیت‌های واقعی در ورود معتبر والد متصل می‌شوند.' : 'Real capabilities connect only after authenticated Parent sign-in.'}><div className="preview-empty"><span className="empty-orb"><Icon name={selected.icon} size={24}/></span><strong>{fa ? 'داده‌ای بارگیری نشده' : 'No data loaded'}</strong><p>{fa ? 'برای مشاهدهٔ اطلاعات خانواده باید وارد شوید. این پیش‌نمایش نه API را دور می‌زند و نه داده می‌سازد.' : 'Sign in to view family data. This preview neither bypasses the API nor fabricates data.'}</p><Link className="btn btn-primary" to="/login">{fa ? 'رفتن به ورود' : 'Go to sign in'}</Link></div></Panel>}<div className="note-box"><Icon name="alert"/><p>{fa ? 'گزارش تماس، مخاطبان و دوربین/مکان‌یابی با دوربین در API موجود نیستند و به این رابط اضافه نشده‌اند.' : 'Call logs, contacts, and camera-based location are not available in the API and are not added here.'}</p></div></main></div></div>;
}

function Brand() { return <Link to="/" className="brand"><span className="brand-mark"><Icon name="shield" size={22}/></span><span><strong>GuardianLink</strong><small>FAMILY CARE</small></span></Link>; }

const mainNav: { to: string; key: 'dashboard' | 'children' | 'notifications' | 'sos' | 'reports' | 'privacy' | 'settings'; icon: string; end?: boolean }[] = [
  { to: '/', key: 'dashboard' as const, icon: 'grid', end: true },
  { to: '/children', key: 'children' as const, icon: 'devices' },
  { to: '/notifications', key: 'notifications' as const, icon: 'bell' },
  { to: '/sos', key: 'sos' as const, icon: 'heart' },
  { to: '/reports', key: 'reports' as const, icon: 'chart' },
];
function AppShell() {
  const { t, language, toggleLanguage, theme, toggleTheme } = useUi(); const { logout } = useAuth(); const request = useApi(); const navigate = useNavigate(); const { data: me } = useQuery({ queryKey: ['me'], queryFn: () => request<import('./api').User>(routes.me) });
  const { data: count } = useQuery({ queryKey: ['unread-count'], queryFn: () => request<{ unread: number }>(routes.unread), refetchInterval: 60_000 });
  const health = useQuery({ queryKey: ['health-live'], queryFn: async () => { const response = await fetch('/health/ready', { credentials: 'omit', cache: 'no-store' }); if (!response.ok) throw new Error(`HTTP ${response.status}`); return response.json() as Promise<{ status: string }>; }, retry: 0, refetchInterval: 60_000 });
  const [drawer, setDrawer] = useState(false);
  const signOut = async () => { await logout(); queryClient.clear(); navigate('/login'); };
  const navItems = [...mainNav, { to: '/privacy', key: 'privacy' as const, icon: 'shield' }, { to: '/settings', key: 'settings' as const, icon: 'settings' }];
  return <div className="app-frame"><a className="skip-link" href="#main-content">{language === 'fa' ? 'رفتن به محتوای اصلی' : 'Skip to main content'}</a><aside className={`sidebar ${drawer ? 'drawer-open' : ''}`}><div className="sidebar-brand"><Brand/><button className="mobile-close icon-btn" aria-label={t('closeMenu')} onClick={() => setDrawer(false)}>×</button></div>
      <div className="side-label">{language === 'fa' ? 'فضای والدین' : 'PARENT SPACE'}</div><nav className="side-nav" aria-label={language === 'fa' ? 'ناوبری اصلی' : 'Main navigation'}>{navItems.map(item => <NavLink key={item.to} to={item.to} end={item.end} onClick={() => setDrawer(false)} className={({ isActive }) => `nav-item ${isActive ? 'selected' : ''}`}><Icon name={item.icon}/><span>{t(item.key)}</span>{item.key === 'notifications' && count?.unread ? <b className="nav-count">{count.unread}</b> : null}</NavLink>)}</nav>
      <div className="sidebar-bottom"><div className="support-card"><span className="support-icon"><Icon name="shield" size={17}/></span><strong>{language === 'fa' ? 'روشن و مسئولانه' : 'Clear by design'}</strong><p>{language === 'fa' ? 'بدون جمع‌آوری مخفیانهٔ محتوای شخصی.' : 'No hidden collection of personal content.'}</p></div><button className="nav-item logout-link" onClick={signOut}><Icon name="lock"/><span>{t('signOut')}</span></button></div></aside>
    {drawer && <button className="drawer-scrim" onClick={() => setDrawer(false)} aria-label={t('closeMenu')}/>}
    <div className="main-column"><header className="topbar"><button className="mobile-menu icon-btn" aria-label={t('openMenu')} onClick={() => setDrawer(true)}><Icon name="menu"/></button><div className="topbar-crumb"><span className="crumb-dot"/> <span>{language === 'fa' ? 'فضای امن خانواده' : 'Family space'}</span></div><div className="topbar-actions"><div className={`api-indicator ${health.isError ? 'api-offline' : ''}`} aria-live="polite" title={t('apiStatus')}><span className="pulse-dot"/>{health.isLoading ? t('loading') : health.isError ? t('offline') : t('online')}</div><button className="icon-btn" onClick={toggleTheme} aria-label={t('theme')} title={t('theme')}><Icon name={theme === 'light' ? 'moon' : 'sun'}/></button><button className="language-btn" onClick={toggleLanguage} aria-label={t('language')}>{language === 'fa' ? 'EN' : 'فا'}</button><div className="user-chip"><span className="avatar">{me?.email?.slice(0, 1).toUpperCase() || 'P'}</span><span className="user-email">{me?.email || t('account')}</span></div></div></header>
      <main id="main-content" className="page-content" tabIndex={-1}><Outlet/></main><footer className="app-footer"><span>GuardianLink · {language === 'fa' ? 'پنل والدین' : 'Parent dashboard'}</span><span>{t('privacyNote')}</span></footer></div>
    <nav className="mobile-nav" aria-label={language === 'fa' ? 'ناوبری' : 'Navigation'}>{mainNav.slice(0, 4).map(item => <NavLink key={item.to} to={item.to} end={item.end} className={({ isActive }) => `mobile-nav-item ${isActive ? 'active' : ''}`}><Icon name={item.icon} size={19}/><small>{t(item.key)}</small></NavLink>)}</nav>
  </div>;
}

function PageHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: ReactNode }) { return <div className="page-heading"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1>{description && <p>{description}</p>}</div>{action}</div>; }
function FamilySetup() {
  const { t, language } = useUi(); const request = useApi(); const qc = useQueryClient(); const [name, setName] = useState('');
  const create = useMutation({ mutationFn: () => request('/v1/families', { method: 'POST', body: jsonBody({ name: name.trim() }) }), onSuccess: () => { qc.invalidateQueries({ queryKey: ['family'] }); qc.invalidateQueries({ queryKey: ['devices'] }); } });
  return <><PageHeading eyebrow={t('family')} title={t('noFamilyTitle')} description={t('noFamily')}/><Panel title={language === 'fa' ? 'ساخت خانواده' : 'Create your family'} subtitle={language === 'fa' ? 'ساخت در backend مشترک؛ خانوادهٔ دوم ساخته نمی‌شود.' : 'Created in the shared backend; only one family is allowed.'}><form className="inline-form" onSubmit={e => { e.preventDefault(); if (name.trim()) create.mutate(); }}><label className="sr-only" htmlFor="family-name">{t('family')}</label><input id="family-name" value={name} onChange={e => setName(e.target.value)} placeholder={language === 'fa' ? 'نام خانواده' : 'Family name'} maxLength={60} required/><button className="btn btn-primary" disabled={create.isPending}>{t('save')}</button></form>{create.isError && <p role="alert" className="form-error">{(create.error as Error).message}</p>}</Panel></>;
}

function SetupReadiness({ familyName, onRefresh }: { familyName: string; onRefresh: () => void }) {
  const { language } = useUi();
  return <Panel
    title={language === 'fa' ? 'راه‌اندازی خانواده' : 'Family setup'}
    subtitle={language === 'fa' ? 'وضعیت بر اساس پاسخ واقعی API؛ دستگاهی هنوز ثبت نشده است.' : 'Based on the actual API response; no device is registered yet.'}
    action={<Link className="btn btn-primary" to="/children">{language === 'fa' ? 'شروع اتصال دستگاه' : 'Start device pairing'}</Link>}
  >
    <ol className="setup-checklist">
      <li><strong>{language === 'fa' ? 'ورود حساب' : 'Account sign-in'}</strong><span>{language === 'fa' ? 'نشست احراز‌شدهٔ این پنل' : 'This dashboard has an authenticated session'}</span></li>
      <li><strong>{language === 'fa' ? 'خانواده' : 'Family'}</strong><span>{familyName}</span></li>
      <li><strong>{language === 'fa' ? 'دستگاه Child' : 'Child device'}</strong><span>{language === 'fa' ? 'هنوز از API دستگاهی دریافت نشده' : 'No device has been returned by the API yet'}</span></li>
      <li><strong>{language === 'fa' ? 'تأیید pairing' : 'Pairing confirmation'}</strong><span>{language === 'fa' ? 'پس از ورود کد و تأیید روی Child، این فهرست را تازه کنید.' : 'After entering the code and confirming on Child, refresh this list.'}</span></li>
    </ol>
    <div className="setup-actions"><button className="btn btn-quiet" onClick={onRefresh}>{language === 'fa' ? 'بررسی دوباره' : 'Check again'}</button><span>{language === 'fa' ? 'تا آن زمان قابلیت‌ها فعال تلقی نمی‌شوند.' : 'Capabilities are not considered active until reported.'}</span></div>
  </Panel>;
}

function OverviewPage() {
  const { t, language } = useUi(); const { family, devices } = useFamily(); const request = useApi();
  const unread = useQuery({ queryKey: ['unread-count'], queryFn: () => request<{ unread: number }>(routes.unread), refetchInterval: 60_000 });
  const sos = useQuery({ queryKey: ['active-sos'], queryFn: () => request<unknown>(routes.sosActive), refetchInterval: 30_000 });
  const active = getSosList(sos.data).filter(s => !['RESOLVED', 'CANCELLED', 'FAILED', 'EXPIRED'].includes(s.status));
  const isLoading = family.isLoading || devices.isLoading;
  if (isLoading) return <LoadState/>;
  if (family.isError) return (family.error as { status?: number }).status === 404 ? <FamilySetup/> : <LoadState error={family.error as Error} onRetry={() => family.refetch()}/>;
  return <><PageHeading eyebrow={language === 'fa' ? 'داشبورد والدین' : 'PARENT DASHBOARD'} title={t('overviewTitle')} description={t('overviewDesc')} action={<button className="btn btn-quiet" onClick={() => { family.refetch(); devices.refetch(); unread.refetch(); sos.refetch(); }}><Icon name="clock" size={16}/>{t('refresh')}</button>}/>
    {devices.isError && <LoadState error={devices.error as Error} onRetry={() => devices.refetch()}/>}
    {devices.data?.length === 0 && <SetupReadiness familyName={family.data?.family.name ?? '—'} onRefresh={() => { family.refetch(); devices.refetch(); }} />}
    <div className="stats-grid"><StatCard label={t('family')} value={family.data?.family.name || '—'} note={language === 'fa' ? `${family.data?.members?.length ?? 0} عضو والد` : `${family.data?.members?.length ?? 0} parent member(s)`} icon="heart" accent="blue"/><StatCard label={t('connectedDevices')} value={devices.data?.length ?? 0} note={language === 'fa' ? 'دستگاه‌های فعال در API' : 'Active devices from API'} icon="devices" accent="mint"/><StatCard label={t('unread')} value={unread.data?.unread ?? '—'} note={language === 'fa' ? 'از مرکز اعلان خانواده' : 'From family notification center'} icon="bell" accent="amber"/><StatCard label={t('activeSos')} value={sos.isError ? '—' : active.length} note={language === 'fa' ? 'وضعیت backend؛ نه تماس با اورژانس' : 'Backend state; no emergency call'} icon="alert" accent="rose"/></div>
    <div className="overview-grid"><Panel title={t('childrenTitle')} subtitle={language === 'fa' ? 'نام و وضعیت بر اساس رکورد دستگاه ثبت‌شده' : 'Names and status as recorded for each device'} action={<Link className="panel-link" to="/children">{t('viewDetails')} <Icon name="arrow" size={15}/></Link>}>
      {!devices.data?.length ? <EmptyState>{t('noDevices')}</EmptyState> : <div className="device-list">{devices.data.map(d => <DeviceRow key={d.id} device={d}/>)}</div>}
    </Panel>
    <Panel title={t('recentActivity')} subtitle={language === 'fa' ? 'وضعیت درخواست‌های کمک فعال' : 'Active help request status'}>{sos.isLoading ? <LoadState/> : sos.isError ? <LoadState error={sos.error as Error} onRetry={() => sos.refetch()}/> : active.length === 0 ? <EmptyState>{t('noActiveSos')}</EmptyState> : <div className="sos-compact-list">{active.slice(0, 4).map(item => <SosCompact key={item.id} item={item}/>)}</div>}<div className="disclaimer-strip"><Icon name="lock" size={16}/><span>{t('emergencyServices')}</span></div></Panel></div>
    <div className="capability-strip"><div className="capability-icon"><Icon name="shield"/></div><div><strong>{t('unsupportedTitle')}</strong><p>{t('unsupportedCalls')} {t('unsupportedCamera')}</p></div><Link to="/privacy" className="panel-link">{t('privacy')} <Icon name="arrow" size={15}/></Link></div>
  </>;
}
function DeviceRow({ device, onRemove }: { device: Device; onRemove?: () => void }) { const { t, language } = useUi(); const tone = device.presence === 'online' ? 'good' : device.health === 'UNKNOWN' ? 'neutral' : 'warn'; return <div className="device-row"><span className="device-avatar"><Icon name="devices"/></span><div className="device-info"><strong>{device.deviceName}</strong><span>{[device.manufacturer, device.model].filter(Boolean).join(' · ') || device.maskedId}</span></div><div className="device-meta"><Pill tone={tone}>{device.presence || device.health}</Pill><small>{t('battery')} · {device.batteryLevel == null ? '—' : `${device.batteryLevel}%`}</small></div><div className="device-sync"><small>{t('lastSync')}</small><span>{formatDate(device.lastSync || device.lastSeen, language)}</span></div>{onRemove && <button className="icon-btn danger-text remove-device" onClick={onRemove} aria-label={language === 'fa' ? `حذف دستگاه ${device.deviceName}` : `Remove device ${device.deviceName}`} title={language === 'fa' ? 'حذف و لغو نشست دستگاه' : 'Remove and revoke device sessions'}>×</button>}<Link className="row-open" to={`/children/${device.id}/usage`} aria-label={`${t('viewDetails')}: ${device.deviceName}`}><Icon name="arrow" size={17}/></Link></div>; }
function DevicesPage() { const { t, language } = useUi(); const { family, devices } = useFamily(); const request = useApi(); const qc = useQueryClient(); const remove = useMutation({ mutationFn: (id: string) => request(`/v1/families/me/devices/${id}`, { method: 'DELETE' }), onSuccess: () => qc.invalidateQueries({ queryKey: ['devices'] }) }); if (devices.isLoading || family.isLoading) return <LoadState/>; if (devices.isError) return <LoadState error={devices.error as Error} onRetry={() => devices.refetch()}/>; return <><PageHeading eyebrow={t('children')} title={t('childrenTitle')} description={family.data ? `${family.data.family.name} · ${devices.data?.length ?? 0}` : t('noFamily')}/><Panel title={t('connectedDevices')} subtitle={language === 'fa' ? 'جزئیات وضعیت از API مشترک' : 'Device status from the shared API'}>{devices.data?.length ? <div className="device-list">{devices.data.map(d => <DeviceRow key={d.id} device={d} onRemove={() => { if (window.confirm(language === 'fa' ? `دستگاه «${d.deviceName}» حذف و نشست‌هایش لغو شود؟` : `Remove “${d.deviceName}” and revoke its sessions?`)) remove.mutate(d.id); }}/>)}</div> : <EmptyState>{t('noDevices')}</EmptyState>}{remove.isError && <p role="alert" className="form-error">{(remove.error as Error).message}</p>}</Panel><PairingManager/><div className="note-box"><Icon name="alert"/><p>{language === 'fa' ? 'Child در backend به‌صورت device شناخته می‌شود؛ این رابط نام کودک یا جزئیات فراتر از API نمی‌سازد.' : 'The backend models a child as a device; this interface does not invent a child name or extra device data.'}</p></div></>; }

function PairingManager() { const { language } = useUi(); const request = useApi(); const [pairing, setPairing] = useState<{ code: string; expiresAt: string } | null>(null); const create = useMutation({ mutationFn: () => request<{ sessionId: string; code: string; expiresAt: string; qrPayload: string }>('/v1/pairing/sessions', { method: 'POST' }), onSuccess: result => setPairing({ code: result.code, expiresAt: result.expiresAt }) }); return <Panel title={language === 'fa' ? 'اتصال دستگاه Child' : 'Pair a Child device'} subtitle={language === 'fa' ? 'کد یک‌بارمصرف کوتاه‌عمر؛ فقط پس از درخواست والد ساخته می‌شود.' : 'A short-lived one-time code is created only on parent request.'}><button className="btn btn-primary" onClick={() => { setPairing(null); create.mutate(); }} disabled={create.isPending}>{create.isPending ? '…' : language === 'fa' ? 'ساخت کد اتصال' : 'Create pairing code'}</button>{create.isError && <p role="alert" className="form-error">{(create.error as Error).message}</p>}{pairing && <div className="pairing-code"><span className="eyebrow">{language === 'fa' ? 'کد یک‌بارمصرف · فقط در حافظه' : 'ONE-TIME CODE · MEMORY ONLY'}</span><strong dir="ltr">{pairing.code}</strong><small>{language === 'fa' ? 'انقضا' : 'Expires'} · {formatDate(pairing.expiresAt, language)}</small><p>{language === 'fa' ? 'کد را فقط در Child app رسمی و هنگام pairing وارد کنید. پس از ترک صفحه/بارگذاری مجدد، این نما کد را نگه نمی‌دارد.' : 'Enter this only in the official Child app during pairing. Leaving or reloading this page clears the displayed code.'}</p></div>}</Panel>; }

function DeviceTabs({ id }: { id: string }) { const { t } = useUi(); const tabs = [{ path: 'usage', label: t('screenTime'), icon: 'clock' }, { path: 'location', label: t('location'), icon: 'pin' }, { path: 'zones', label: t('safeZones'), icon: 'pin' }, { path: 'apps', label: t('restrictions'), icon: 'shield' }, { path: 'web-safety', label: t('webSafety'), icon: 'lock' }]; return <nav className="device-tabs" aria-label={t('childNav')}>{tabs.map(tab => <NavLink key={tab.path} to={`/children/${id}/${tab.path}`} className={({ isActive }) => `device-tab ${isActive ? 'active' : ''}`}><Icon name={tab.icon} size={17}/>{tab.label}</NavLink>)}</nav>; }
function NavigateToUsage() { const { deviceId = '' } = useParams(); return <Navigate to={`/children/${deviceId}/usage`} replace/>; }
function useSelectedDevice() { const { deviceId = '' } = useParams(); const { devices } = useFamily(); return { id: deviceId, device: devices.data?.find(d => d.id === deviceId), devices }; }
function DevicePageTitle({ title, sub }: { title: string; sub: string }) { const { t } = useUi(); const { id, device, devices } = useSelectedDevice(); if (devices.isLoading) return <LoadState/>; if (!device) return <><PageHeading eyebrow={t('childDevice')} title={t('noFamilyTitle')}/><LoadState error={new Error(t('noPermission'))}/></>; return <><PageHeading eyebrow={`${t('childDevice')} · ${device.deviceName}`} title={title} description={`${sub} · ${device.model || device.maskedId}`}/><DeviceTabs id={id}/></>; }
function UsagePage() {
  const { id, device, devices } = useSelectedDevice(); const { t, language } = useUi(); const request = useApi(); const qc = useQueryClient(); const [limit, setLimit] = useState('');
  const report = useQuery({ queryKey: ['usage-report', id], queryFn: () => request<UsageReport>(dpath(id, 'screen-time/report')), enabled: !!device });
  const settings = report.data?.settings;
  const save = useMutation({ mutationFn: () => request(dpath(id, 'screen-time/settings'), { method: 'POST', body: jsonBody({ dailyLimitMinutes: Number(limit), nearPct: settings?.nearPct ?? null, enabled: true }) }), onSuccess: () => { qc.invalidateQueries({ queryKey: ['usage-report', id] }); setLimit(''); } });
  if (devices.isLoading) return <LoadState/>; if (!device) return <DevicePageTitle title={t('screenTime')} sub={t('screenTime')}/>;
  return <><DevicePageTitle title={t('screenTime')} sub={t('screenTime')}/>{report.isLoading ? <LoadState/> : report.isError ? <LoadState error={report.error as Error} onRetry={() => report.refetch()}/> : <>
    <div className="stats-grid two-stats"><StatCard label={t('today')} value={duration(report.data!.today.totalMinutes, language)} note={report.data!.today.state} icon="clock" accent="blue"/><StatCard label={t('thisWeek')} value={duration(report.data!.weekly.totalMinutes, language)} note={`${t('average')}: ${duration(report.data!.weekly.averageMinutes, language)}`} icon="chart" accent="mint"/></div>
    <div className="content-grid"><Panel title={language === 'fa' ? 'روند هفتگی' : 'Weekly trend'} subtitle={language === 'fa' ? 'دقایق مصرف گزارش‌شدهٔ دستگاه' : 'Reported usage minutes from this device'}><UsageChart days={report.data!.weekly.days}/></Panel><Panel title={language === 'fa' ? 'حد روزانه' : 'Daily limit'} subtitle={language === 'fa' ? 'تنظیم از API؛ اجرای واقعی وابسته به قابلیت دستگاه' : 'Saved by API; enforcement depends on device capability'}><div className="limit-number">{report.data!.today.limitEnabled && report.data!.today.limitMinutes != null ? duration(report.data!.today.limitMinutes, language) : '—'}</div><Pill tone={report.data!.today.limitEnabled ? 'good' : 'neutral'}>{report.data!.today.limitEnabled ? (language === 'fa' ? 'روشن' : 'Enabled') : (language === 'fa' ? 'خاموش' : 'Disabled')}</Pill><form className="inline-form" onSubmit={e => { e.preventDefault(); if (Number(limit) > 0 && Number.isFinite(Number(limit))) save.mutate(); }}><label className="sr-only" htmlFor="limit-input">{language === 'fa' ? 'دقایق محدودیت روزانه' : 'Daily limit in minutes'}</label><input id="limit-input" type="number" min="1" max="1440" value={limit} onChange={e => setLimit(e.target.value)} placeholder={language === 'fa' ? 'دقیقهٔ جدید' : 'New limit in minutes'}/><button className="btn btn-primary" disabled={save.isPending || !limit}>{save.isPending ? '…' : t('save')}</button></form>{save.isError && <p role="alert" className="form-error">{(save.error as Error).message}</p>}</Panel></div>
    <Panel title={language === 'fa' ? 'بیشترین استفادهٔ امروز' : 'Top apps today'}>{report.data!.today.topApps.length ? <div className="app-usage-list">{report.data!.today.topApps.map(app => <div className="usage-row" key={app.packageName}><div><strong>{app.appName}</strong><small>{app.category}</small></div><div className="usage-bar"><i style={{ width: `${Math.max(3, Math.min(100, app.percent))}%` }}/></div><b>{duration(app.usageMinutes, language)}</b></div>)}</div> : <EmptyState>{t('empty')}</EmptyState>}</Panel>
    <div className="note-box"><Icon name="alert"/><p>{language === 'fa' ? 'گزارش مصرف طبق آخرین همگام‌سازی Child است. ثبت محدودیت در API به معنی اجرای قطعی در همهٔ حالت‌های Android نیست.' : 'Usage reflects the latest Child sync. Saving a limit does not guarantee enforcement in every Android mode.'}</p></div>
  </>}</>;
}
function UsageChart({ days }: { days: { date: string; totalMinutes: number }[] }) { const { language } = useUi(); const max = Math.max(1, ...days.map(d => d.totalMinutes)); return <div className="bar-chart" role="img" aria-label={language === 'fa' ? 'نمودار زمان استفادهٔ هفتگی بر اساس دادهٔ API' : 'Weekly usage chart from API data'}>{days.map(day => <div className="bar-col" key={day.date}><div className="bar-value">{day.totalMinutes ? Math.round(day.totalMinutes / 60 * 10) / 10 : '0'}</div><div className="bar-track"><i style={{ height: `${Math.max(day.totalMinutes ? 5 : 0, day.totalMinutes / max * 100)}%` }}/></div><small>{new Date(`${day.date}T12:00:00`).toLocaleDateString(language === 'fa' ? 'fa-IR' : 'en-GB', { weekday: 'short' })}</small></div>)}</div>; }

function LocationPage() {
  const { id, device, devices } = useSelectedDevice();
  const { t, language } = useUi();
  const request = useApi();
  const qc = useQueryClient();
  const current = useQuery({ queryKey: ['location-current', id], queryFn: () => request<LocationCurrent>(dpath(id, 'location/current')), enabled: !!device });
  const settings = useQuery({ queryKey: ['location-settings', id], queryFn: () => request<{ sharingEnabled: boolean; retentionDays: number }>(dpath(id, 'location/settings')), enabled: !!device });
  const history = useQuery({ queryKey: ['location-history', id], queryFn: () => request<{ points: NonNullable<LocationCurrent['fix']>[]; retentionDays: number; sharingEnabled: boolean }>(`${dpath(id, 'location/history')}?limit=30`), enabled: !!device });
  const update = useMutation({ mutationFn: (enabled: boolean) => request(dpath(id, 'location/settings'), { method: 'POST', body: jsonBody({ sharingEnabled: enabled, retentionDays: settings.data?.retentionDays ?? null }) }), onSuccess: () => { qc.invalidateQueries({ queryKey: ['location-current', id] }); qc.invalidateQueries({ queryKey: ['location-settings', id] }); } });
  if (devices.isLoading) return <LoadState/>;
  if (!device) return <DevicePageTitle title={t('location')} sub={t('location')}/>;
  return <>
    <DevicePageTitle title={t('location')} sub={t('location')}/>
    {current.isLoading || settings.isLoading ? <LoadState/> : current.isError ? <LoadState error={current.error as Error} onRetry={() => current.refetch()}/> : <>
      <div className="location-layout">
        <Panel title={language === 'fa' ? 'آخرین موقعیت' : 'Latest location'} subtitle={t('locationDisclaimer')}>
          {current.data?.fix ? <>
            <div className="coordinate-visual"><div className="coord-grid"><span className="coord-cross"/><span className="coord-point"><i/></span><span className="coord-label">{t('mapLabel')}</span></div></div>
            <div className="coordinate-grid">
              <Coordinate label={t('coordinates')} value={`${current.data.fix.latitude.toFixed(5)}, ${current.data.fix.longitude.toFixed(5)}`}/>
              <Coordinate label={t('accuracy')} value={current.data.fix.accuracyM == null ? '—' : `±${Math.round(current.data.fix.accuracyM)} m`}/>
              <Coordinate label={t('timestamp')} value={formatDate(current.data.fix.timestamp, language)}/>
              <Coordinate label={t('status')} value={current.data.fix.isCurrent ? 'CURRENT' : 'LAST KNOWN'}/>
            </div>
          </> : <EmptyState>{t('noLocation')}</EmptyState>}
          <div className="disclaimer-strip"><Icon name="lock" size={16}/><span>{t('privacyNoThirdParty')}</span></div>
        </Panel>
        <Panel title={language === 'fa' ? 'وضعیت دسترسی دستگاه' : 'Device-reported status'}>
          <div className="status-list">
            <div><span>{language === 'fa' ? 'اشتراک‌گذاری' : 'Sharing'}</span><Pill tone={current.data?.sharingEnabled ? 'good' : 'warn'}>{String(current.data?.sharingEnabled ?? false)}</Pill></div>
            <div><span>{language === 'fa' ? 'مجوز موقعیت' : 'Location permission'}</span><Pill>{current.data?.permissionStatus || t('noPermission')}</Pill></div>
            <div><span>{language === 'fa' ? 'ارائه‌دهنده' : 'Provider'}</span><Pill>{current.data?.providerStatus || '—'}</Pill></div>
            <div><span>{language === 'fa' ? 'سلامت' : 'Health'}</span><Pill>{current.data?.health || '—'}</Pill></div>
            <div><span>{language === 'fa' ? 'نگهداری' : 'Retention'}</span><Pill>{settings.data?.retentionDays ?? current.data?.retentionDays ?? '—'} {language === 'fa' ? 'روز' : 'days'}</Pill></div>
          </div>
          <button className={`btn ${settings.data?.sharingEnabled ? 'btn-danger-soft' : 'btn-primary'} btn-block gap-top`} onClick={() => { if (settings.data?.sharingEnabled && !window.confirm(language === 'fa' ? 'اشتراک‌گذاری موقعیت خاموش شود؟' : 'Turn off location sharing?')) return; update.mutate(!settings.data?.sharingEnabled); }} disabled={update.isPending}>{settings.data?.sharingEnabled ? (language === 'fa' ? 'خاموش‌کردن اشتراک' : 'Turn sharing off') : (language === 'fa' ? 'روشن‌کردن اشتراک' : 'Turn sharing on')}</button>
          {update.isError && <p className="form-error">{(update.error as Error).message}</p>}
        </Panel>
      </div>
      <Panel title={language === 'fa' ? 'تاریخچهٔ موقعیت' : 'Location history'} subtitle={language === 'fa' ? `آخرین نقاطی که API نگه داشته · ${history.data?.retentionDays ?? '—'} روز` : `Latest points retained by API · ${history.data?.retentionDays ?? '—'} days`}>
        {history.isLoading ? <LoadState/> : history.isError ? <LoadState error={history.error as Error} onRetry={() => history.refetch()}/> : !history.data?.points?.length ? <EmptyState>{t('empty')}</EmptyState> : <div className="table-wrap"><table><thead><tr><th>{t('timestamp')}</th><th>{t('coordinates')}</th><th>{t('accuracy')}</th><th>{t('source')}</th></tr></thead><tbody>{history.data.points.map((p, i) => <tr key={`${p.timestamp}-${i}`}><td>{formatDate(p.timestamp, language)}</td><td dir="ltr">{p.latitude.toFixed(5)}, {p.longitude.toFixed(5)}</td><td>{p.accuracyM == null ? '—' : `±${Math.round(p.accuracyM)}m`}</td><td>{p.source}</td></tr>)}</tbody></table></div>}
        <p className="micro-note">{t('locationDisclaimer')}</p>
      </Panel>
    </>}
  </>;
}
function Coordinate({ label, value }: { label: string; value: string }) { return <div className="coordinate-item"><small>{label}</small><strong>{value}</strong></div>; }

function ZonesPage() {
  const { id, device, devices } = useSelectedDevice(); const { t, language } = useUi(); const request = useApi(); const qc = useQueryClient(); const [form, setForm] = useState({ name: '', latitude: '', longitude: '', radiusM: '300' });
  const zones = useQuery({ queryKey: ['zones', id], queryFn: () => request<ZonesResponse>(dpath(id, 'geofences')), enabled: !!device });
  const create = useMutation({ mutationFn: () => request(dpath(id, 'geofences'), { method: 'POST', body: jsonBody({ name: form.name, latitude: Number(form.latitude), longitude: Number(form.longitude), radiusM: Number(form.radiusM), enabled: true }) }), onSuccess: () => { qc.invalidateQueries({ queryKey: ['zones', id] }); setForm({ name: '', latitude: '', longitude: '', radiusM: '300' }); } });
  const remove = useMutation({ mutationFn: (zoneId: string) => request(dpath(id, `geofences/${zoneId}`), { method: 'DELETE' }), onSuccess: () => qc.invalidateQueries({ queryKey: ['zones', id] }) });
  if (devices.isLoading) return <LoadState/>; if (!device) return <DevicePageTitle title={t('safeZones')} sub={t('safeZones')}/>;
  return <><DevicePageTitle title={t('safeZones')} sub={t('safeZones')}/>{zones.isLoading ? <LoadState/> : zones.isError ? <LoadState error={zones.error as Error} onRetry={() => zones.refetch()}/> : <>
    <div className="stats-grid three-stats"><StatCard label={language === 'fa' ? 'محدودهٔ فعال' : 'Active zones'} value={`${zones.data!.active}/${zones.data!.maxZones}`} note={language === 'fa' ? 'سقف بازگشتی از API' : 'API-provided limit'} icon="pin"/><StatCard label={language === 'fa' ? 'کمترین شعاع' : 'Minimum radius'} value={`${zones.data!.minRadiusM} m`} note={`${language === 'fa' ? 'بیشترین' : 'Maximum'} ${zones.data!.maxRadiusM} m`} icon="chart" accent="mint"/><StatCard label={language === 'fa' ? 'حداقل دقت fix' : 'Minimum fix accuracy'} value={`≤${zones.data!.minAccuracyM} m`} note={t('delayDisclaimer')} icon="clock" accent="amber"/></div>
    <Panel title={language === 'fa' ? 'محدوده‌های تعریف‌شده' : 'Configured zones'} subtitle={t('delayDisclaimer')}>{zones.data!.zones.length ? <div className="zone-list">{zones.data!.zones.map(z => <div className="zone-row" key={z.id}><span className="zone-icon"><Icon name="pin"/></span><div className="zone-main"><strong>{z.name}</strong><small>{z.radiusM} m · {z.latitude.toFixed(4)}, {z.longitude.toFixed(4)}</small></div><Pill tone={z.state === 'inside' ? 'good' : z.state === 'error' ? 'bad' : 'neutral'}>{z.state}</Pill><span className="zone-last">{formatDate(z.lastTransitionAt, language)}</span><button className="icon-btn danger-text" aria-label={language === 'fa' ? `حذف ${z.name}` : `Delete ${z.name}`} onClick={() => { if (window.confirm(language === 'fa' ? `محدودهٔ «${z.name}» حذف شود؟` : `Delete zone “${z.name}”?`)) remove.mutate(z.id); }}>×</button></div>)}</div> : <EmptyState>{t('empty')}</EmptyState>}</Panel>
    <Panel title={language === 'fa' ? 'افزودن محدوده' : 'Add a zone'} subtitle={language === 'fa' ? 'مختصات و شعاع واقعی به API ارسال می‌شوند.' : 'Coordinates and radius are sent to the API.'}><form className="zone-form" onSubmit={e => { e.preventDefault(); if (Number.isFinite(Number(form.latitude)) && Number.isFinite(Number(form.longitude))) create.mutate(); }}><label>{language === 'fa' ? 'نام' : 'Name'}<input required maxLength={80} value={form.name} onChange={e => setForm({ ...form, name: e.target.value })}/></label><label>Latitude<input required type="number" min="-90" max="90" step="any" value={form.latitude} onChange={e => setForm({ ...form, latitude: e.target.value })}/></label><label>Longitude<input required type="number" min="-180" max="180" step="any" value={form.longitude} onChange={e => setForm({ ...form, longitude: e.target.value })}/></label><label>{language === 'fa' ? 'شعاع (متر)' : 'Radius (m)'}<input required type="number" min={zones.data!.minRadiusM} max={zones.data!.maxRadiusM} value={form.radiusM} onChange={e => setForm({ ...form, radiusM: e.target.value })}/></label><button className="btn btn-primary" disabled={create.isPending || zones.data!.active >= zones.data!.maxZones}>{t('save')}</button></form>{(create.isError || remove.isError) && <p role="alert" className="form-error">{((create.error || remove.error) as Error).message}</p>}</Panel>
  </>}</>;
}

function RestrictionsPage() {
  const { id, device, devices } = useSelectedDevice(); const { t, language } = useUi(); const request = useApi(); const qc = useQueryClient(); const [pkg, setPkg] = useState(''); const [ruleType, setRuleType] = useState('LIMITED'); const [minutes, setMinutes] = useState('60');
  const rules = useQuery({ queryKey: ['app-rules', id], queryFn: () => request<AppRulesResponse>(dpath(id, 'app-rules')), enabled: !!device });
  const catalog = useQuery({ queryKey: ['app-catalog', id], queryFn: () => request<CatalogResponse>(dpath(id, 'apps')), enabled: !!device });
  const create = useMutation({ mutationFn: () => request(dpath(id, 'app-rules'), { method: 'POST', body: jsonBody({ packageName: pkg, ruleType, dailyLimitSeconds: ruleType === 'LIMITED' ? Number(minutes) * 60 : null, enabled: true }) }), onSuccess: () => { qc.invalidateQueries({ queryKey: ['app-rules', id] }); qc.invalidateQueries({ queryKey: ['app-catalog', id] }); setPkg(''); } });
  const toggle = useMutation({ mutationFn: (rule: AppRulesResponse['rules'][number]) => request(dpath(id, `app-rules/${rule.id}`), { method: 'PUT', body: jsonBody({ enabled: !rule.enabled, expectedVersion: rule.version }) }), onSuccess: () => qc.invalidateQueries({ queryKey: ['app-rules', id] }) });
  const remove = useMutation({ mutationFn: (rule: AppRulesResponse['rules'][number]) => request(dpath(id, `app-rules/${rule.id}?expectedVersion=${rule.version}`), { method: 'DELETE' }), onSuccess: () => qc.invalidateQueries({ queryKey: ['app-rules', id] }) });
  if (devices.isLoading) return <LoadState/>; if (!device) return <DevicePageTitle title={t('restrictions')} sub={t('restrictions')}/>;
  return <><DevicePageTitle title={t('restrictions')} sub={t('restrictions')}/>{rules.isLoading || catalog.isLoading ? <LoadState/> : rules.isError ? <LoadState error={rules.error as Error} onRetry={() => rules.refetch()}/> : catalog.isError ? <LoadState error={catalog.error as Error} onRetry={() => catalog.refetch()}/> : <>
    <div className="capability-strip"><div className="capability-icon"><Icon name="alert"/></div><div><strong>{t('enforcement')}: {catalog.data!.enforcementCapability} · {rules.data!.managementMode}</strong><p>{language === 'fa' ? `دسترسی مصرف: ${rules.data!.usageAccessGranted ? 'مجاز' : 'ندارد'} · همگام‌سازی policy: ${formatDate(catalog.data!.policyLastSyncAt, language)}` : `Usage access: ${rules.data!.usageAccessGranted ? 'granted' : 'not granted'} · policy sync: ${formatDate(catalog.data!.policyLastSyncAt, language)}`}</p></div></div>
    <Panel title={language === 'fa' ? 'قواعد فعلی' : 'Current rules'} subtitle={t('serviceOnly')}>{rules.data!.rules.length ? <div className="rule-list">{rules.data!.rules.map(r => <div className="rule-row" key={r.id}><div><strong>{r.appName}</strong><small>{r.packageName} · {r.ruleType}{r.dailyLimitSeconds ? ` · ${Math.round(r.dailyLimitSeconds / 60)} min` : ''}</small><small>{t('enforcement')}: {r.lastEnforcementStatus}{r.lastEnforcementAt ? ` · ${formatDate(r.lastEnforcementAt, language)}` : ''}</small></div><Pill tone={r.lastEnforcementStatus === 'ENFORCED' ? 'good' : r.lastEnforcementStatus === 'UNSUPPORTED' || r.lastEnforcementStatus === 'FAILED' ? 'warn' : 'neutral'}>{r.enabled ? (language === 'fa' ? 'روشن' : 'Enabled') : (language === 'fa' ? 'خاموش' : 'Disabled')}</Pill><button className="btn btn-quiet" onClick={() => toggle.mutate(r)}>{r.enabled ? (language === 'fa' ? 'خاموش‌کردن' : 'Disable') : (language === 'fa' ? 'روشن‌کردن' : 'Enable')}</button><button className="icon-btn danger-text" aria-label={language === 'fa' ? `حذف قاعده ${r.appName}` : `Delete rule ${r.appName}`} onClick={() => { if (window.confirm(language === 'fa' ? `قاعدهٔ ${r.appName} حذف شود؟` : `Delete rule for ${r.appName}?`)) remove.mutate(r); }}>×</button></div>)}</div> : <EmptyState>{t('empty')}</EmptyState>}</Panel>
    <Panel title={language === 'fa' ? 'افزودن قاعدهٔ اپ' : 'Add an app rule'}><form className="zone-form" onSubmit={e => { e.preventDefault(); if (pkg) create.mutate(); }}><label>{language === 'fa' ? 'اپ نصب‌شده' : 'Installed app'}<select value={pkg} onChange={e => setPkg(e.target.value)} required><option value="">{language === 'fa' ? 'انتخاب…' : 'Select…'}</option>{catalog.data!.apps.filter(a => a.installed).map(a => <option key={a.packageName} value={a.packageName}>{a.appName} · {a.packageName}</option>)}</select></label><label>{language === 'fa' ? 'نوع قاعده' : 'Rule type'}<select value={ruleType} onChange={e => setRuleType(e.target.value)}><option value="LIMITED">LIMITED</option><option value="RESTRICTED">RESTRICTED</option><option value="SCHEDULED">SCHEDULED</option><option value="ALLOW">ALLOW</option></select></label>{ruleType === 'LIMITED' && <label>{language === 'fa' ? 'سقف روزانه (دقیقه)' : 'Daily limit (minutes)'}<input type="number" min="1" max="1440" value={minutes} onChange={e => setMinutes(e.target.value)}/></label>}<button className="btn btn-primary" disabled={create.isPending || !pkg}>{t('save')}</button></form>{(create.isError || toggle.isError || remove.isError) && <p role="alert" className="form-error">{((create.error || toggle.error || remove.error) as Error).message}</p>}</Panel>
    <p className="micro-note">{language === 'fa' ? 'قواعد ممکن است بسته به حالت مدیریت Android اجرا نشوند. وضعیت واقعی از backend نمایش داده شده؛ این وب‌سایت هیچ کنترل پنهان یا دورزدنی اعمال نمی‌کند.' : 'Rules may not be enforced in every Android management mode. The backend-reported state is shown; this site does not add hidden or bypass controls.'}</p>
  </>}</>;
}

function WebSafetyPage() {
  const { id, device, devices } = useSelectedDevice(); const { t, language } = useUi(); const request = useApi(); const qc = useQueryClient(); const [domain, setDomain] = useState('');
  const settings = useQuery({ queryKey: ['web-safety', id], queryFn: () => request<WebSettings>(dpath(id, 'web-safety')), enabled: !!device });
  const events = useQuery({ queryKey: ['web-events', id], queryFn: () => request<{ events: { id: string; eventType: string; ts: string; reasonCode: string; source: string }[] }>(dpath(id, 'web-safety/events?limit=30')), enabled: !!device });
  const update = useMutation({ mutationFn: (enabled: boolean) => request(dpath(id, 'web-safety'), { method: 'PUT', body: jsonBody({ enabled, defaultPolicy: settings.data?.defaultPolicy || 'ALLOW', requestedMode: settings.data?.requestedMode || 'NORMAL', alertsEnabled: settings.data?.alertsEnabled ?? true, expectedVersion: settings.data?.ruleVersion ?? 0 }) }), onSuccess: () => qc.invalidateQueries({ queryKey: ['web-safety', id] }) });
  const addRule = useMutation({ mutationFn: () => request(dpath(id, 'web-safety/rules'), { method: 'POST', body: jsonBody({ ruleType: 'DOMAIN', domain, scope: 'DOMAIN_AND_SUBDOMAINS', action: 'BLOCK', enabled: true, expectedVersion: null }) }), onSuccess: () => { qc.invalidateQueries({ queryKey: ['web-safety', id] }); setDomain(''); } });
  const deleteRule = useMutation({ mutationFn: (rule: WebSettings['rules'][number]) => request(dpath(id, `web-safety/rules/${rule.id}?expectedVersion=${rule.version}`), { method: 'DELETE' }), onSuccess: () => qc.invalidateQueries({ queryKey: ['web-safety', id] }) });
  if (devices.isLoading) return <LoadState/>; if (!device) return <DevicePageTitle title={t('webSafety')} sub={t('webSafety')}/>;
  return <><DevicePageTitle title={t('webSafety')} sub={t('webSafety')}/>{settings.isLoading ? <LoadState/> : settings.isError ? <LoadState error={settings.error as Error} onRetry={() => settings.refetch()}/> : <>
    <div className="web-status-card"><div><span className="eyebrow">{language === 'fa' ? 'وضعیت گزارش‌شدهٔ دستگاه' : 'DEVICE-REPORTED STATUS'}</span><h2>{settings.data!.reportedStatus || 'UNKNOWN'}</h2><p>{settings.data!.reportedReason || t('noPermission')}</p></div><div className="web-status-side"><Pill tone={settings.data!.enabled ? 'good' : 'warn'}>{settings.data!.enabled ? (language === 'fa' ? 'سیاست روشن' : 'Policy enabled') : (language === 'fa' ? 'خاموش' : 'Disabled')}</Pill><small>{settings.data!.reportedMode} · DNS: {settings.data!.dnsStatus} · VPN: {settings.data!.vpnStatus}</small><button className={`btn ${settings.data!.enabled ? 'btn-danger-soft' : 'btn-primary'}`} onClick={() => update.mutate(!settings.data!.enabled)} disabled={update.isPending}>{settings.data!.enabled ? (language === 'fa' ? 'خاموش‌کردن سیاست' : 'Disable policy') : (language === 'fa' ? 'روشن‌کردن سیاست' : 'Enable policy')}</button></div></div>
    <Panel title={language === 'fa' ? 'قواعد دامنه' : 'Domain rules'} subtitle={language === 'fa' ? 'فقط تنظیمات و رویدادهای بدون محتوای وب' : 'Configuration and non-content events only'}>{settings.data!.rules.length ? <div className="rule-list">{settings.data!.rules.map(r => <div className="rule-row" key={r.id}><div><strong>{r.domain || r.category || r.ruleType}</strong><small>{r.action} · {r.ruleType} · v{r.version}</small></div><Pill tone={r.enabled ? 'good' : 'neutral'}>{r.enabled ? (language === 'fa' ? 'روشن' : 'Enabled') : (language === 'fa' ? 'خاموش' : 'Disabled')}</Pill><small>{r.categoryEnforceable ? (language === 'fa' ? 'قابل اجرا' : 'Enforceable') : (language === 'fa' ? 'اجرای تأییدنشده' : 'Enforcement unverified')}</small><button className="icon-btn danger-text" aria-label={language === 'fa' ? 'حذف قاعده' : 'Delete rule'} onClick={() => { if (window.confirm(language === 'fa' ? 'این قاعده حذف شود؟' : 'Delete this rule?')) deleteRule.mutate(r); }}>×</button></div>)}</div> : <EmptyState>{t('empty')}</EmptyState>}<form className="inline-form domain-form" onSubmit={e => { e.preventDefault(); if (domain.trim()) addRule.mutate(); }}><label className="sr-only" htmlFor="domain-input">{language === 'fa' ? 'دامنه' : 'Domain'}</label><input id="domain-input" value={domain} onChange={e => setDomain(e.target.value)} placeholder="example.org" dir="ltr" required maxLength={253}/><button className="btn btn-primary" disabled={addRule.isPending}>{language === 'fa' ? 'افزودن مسدودسازی' : 'Add block rule'}</button></form>{(update.isError || addRule.isError || deleteRule.isError) && <p className="form-error">{((update.error || addRule.error || deleteRule.error) as Error).message}</p>}</Panel>
    <Panel title={language === 'fa' ? 'رویدادهای سیاست' : 'Policy events'}>{events.isLoading ? <LoadState/> : events.isError ? <LoadState error={events.error as Error} onRetry={() => events.refetch()}/> : events.data!.events.length ? <div className="event-list">{events.data!.events.map(ev => <div className="event-row" key={ev.id}><span className="event-dot"/><div><strong>{ev.eventType}</strong><small>{ev.reasonCode} · {ev.source}</small></div><time>{formatDate(ev.ts, language)}</time></div>)}</div> : <EmptyState>{t('empty')}</EmptyState>}</Panel>
    <div className="note-box"><Icon name="lock"/><p>{language === 'fa' ? 'API عمداً URL بازدیدشده، جست‌وجو، یا محتوای صفحه را نگه نمی‌دارد. قابلیت دسته‌بندی هم فقط وقتی categoryProviderAvailable=true باشد قابل اتکا است.' : 'The API deliberately does not store visited URLs, searches, or page contents. Category rules are only supported when categoryProviderAvailable is true.'}</p></div>
  </>}</>;
}

function NotificationsPage() {
  const { t, language } = useUi(); const request = useApi(); const qc = useQueryClient(); const [unreadOnly, setUnreadOnly] = useState(false);
  const page = useQuery({ queryKey: ['notifications', unreadOnly], queryFn: () => request<NotificationPage>(`${routes.notifications}?limit=40${unreadOnly ? '&unread=true' : ''}`), refetchInterval: 60_000 });
  const action = useMutation({ mutationFn: ({ id, verb }: { id: string; verb: string }) => request(`/v1/families/me/notifications/${id}/${verb}`, { method: 'POST' }), onSuccess: () => { qc.invalidateQueries({ queryKey: ['notifications'] }); qc.invalidateQueries({ queryKey: ['unread-count'] }); } });
  const allRead = useMutation({ mutationFn: () => request(`${routes.notifications}/read-all`, { method: 'POST' }), onSuccess: () => { qc.invalidateQueries({ queryKey: ['notifications'] }); qc.invalidateQueries({ queryKey: ['unread-count'] }); } });
  const labels: Record<string, string> = { BATTERY: language === 'fa' ? 'باتری' : 'Battery', CONNECTIVITY: language === 'fa' ? 'اتصال' : 'Connectivity', LOCATION: language === 'fa' ? 'موقعیت' : 'Location', GEOFENCE: language === 'fa' ? 'محدوده' : 'Zone', APP_USAGE: language === 'fa' ? 'مصرف اپ' : 'App usage', WEB_SAFETY: 'Web Safety', PERMISSION: language === 'fa' ? 'مجوز' : 'Permission', EMERGENCY: language === 'fa' ? 'درخواست کمک' : 'Help request' };
  return <><PageHeading eyebrow={t('notifications')} title={t('notifications')} description={language === 'fa' ? 'مرکز اعلان خانواده از API؛ بدون push ادعایی' : 'Family notification center from the API; no claimed push delivery'} action={<button className="btn btn-quiet" onClick={() => allRead.mutate()} disabled={!page.data?.items.some(n => !n.isRead)}>{t('readAll')}</button>}/><div className="filter-row"><button className={`filter-chip ${!unreadOnly ? 'chosen' : ''}`} onClick={() => setUnreadOnly(false)}>{language === 'fa' ? 'همه' : 'All'}</button><button className={`filter-chip ${unreadOnly ? 'chosen' : ''}`} onClick={() => setUnreadOnly(true)}>{t('unread')}</button>{page.data && <Pill>{page.data.unreadCount} {t('unread')}</Pill>}</div>
    {page.isLoading ? <LoadState/> : page.isError ? <LoadState error={page.error as Error} onRetry={() => page.refetch()}/> : !page.data!.items.length ? <Panel title={t('notifications')}><EmptyState>{t('empty')}</EmptyState></Panel> : <Panel title={language === 'fa' ? 'آخرین رویدادها' : 'Latest events'} subtitle={language === 'fa' ? 'مرتب‌شده بر پایهٔ زمان سرور' : 'Sorted by server timestamp'}><div className="notification-list">{page.data!.items.map(n => <NotificationRow key={n.id} item={n} category={labels[n.category] || n.category} onAction={verb => action.mutate({ id: n.id, verb })}/>)}</div></Panel>}
  </>;
}
function NotificationRow({ item, category, onAction }: { item: Notification; category: string; onAction: (verb: string) => void }) { const { t, language } = useUi(); return <article className={`notification-row ${item.isRead ? '' : 'unread-row'}`}><span className={`severity-mark ${item.severity.toLowerCase()}`}><Icon name={item.category === 'EMERGENCY' ? 'heart' : item.category === 'LOCATION' ? 'pin' : 'bell'} size={17}/></span><div className="notification-main"><div className="notification-title"><strong>{item.eventType.replaceAll('_', ' ')}</strong><Pill tone={item.severity === 'CRITICAL' ? 'bad' : item.severity === 'WARNING' ? 'warn' : 'neutral'}>{item.severity}</Pill><span className="category-tag">{category}</span></div><p>{item.deviceName} · {item.status}{item.metadata && item.metadata !== '{}' ? ` · ${safeMeta(item.metadata)}` : ''}</p><time>{formatDate(item.occurredAt, language)}</time></div><div className="notification-actions">{!item.isRead && <button className="btn btn-quiet" onClick={() => onAction('read')}>{language === 'fa' ? 'خواندم' : 'Read'}</button>}{item.status !== 'ACKNOWLEDGED' && item.status !== 'RESOLVED' && <button className="icon-btn" aria-label={t('acknowledge')} title={t('acknowledge')} onClick={() => onAction('acknowledge')}><Icon name="shield" size={17}/></button>}{item.status !== 'RESOLVED' && <button className="icon-btn" aria-label={t('resolve')} title={t('resolve')} onClick={() => onAction('resolve')}>✓</button>}</div></article>; }
function safeMeta(value: string) { try { const obj = JSON.parse(value) as Record<string, unknown>; const allowed = new Set(['package_name', 'zone', 'reason_code', 'permission', 'battery_level', 'state', 'status', 'category']); return Object.entries(obj).filter(([k, v]) => allowed.has(k) && ['string', 'number', 'boolean'].includes(typeof v)).slice(0, 3).map(([k, v]) => `${k}: ${String(v).slice(0, 60)}`).join(' · '); } catch { return ''; } }

function SosPage() {
  const { t, language } = useUi(); const request = useApi(); const qc = useQueryClient();
  const active = useQuery({ queryKey: ['active-sos'], queryFn: () => request<unknown>(routes.sosActive), refetchInterval: 30_000 });
  const { devices } = useFamily();
  const list = getSosList(active.data);
  const action = useMutation({ mutationFn: ({ id, verb }: { id: string; verb: 'acknowledge' | 'resolve' }) => request(`/v1/families/me/sos/${id}/${verb}`, { method: 'POST', ...(verb === 'resolve' ? { body: jsonBody({ note: null }) } : {}) }), onSuccess: () => { qc.invalidateQueries({ queryKey: ['active-sos'] }); qc.invalidateQueries({ queryKey: ['notifications'] }); } });
  const history = useQuery({ queryKey: ['sos-history', devices.data?.map(d => d.id)], queryFn: async () => { const all = await Promise.all((devices.data || []).map(d => request<{ sessions: Sos[]; nextBefore: string | null }>(`/v1/families/me/devices/${d.id}/sos/history?limit=20`))); return all.flatMap(v => v.sessions || []); }, enabled: !!devices.data?.length });
  return <><PageHeading eyebrow={t('sos')} title={t('sos')} description={t('emergencyServices')}/>{active.isLoading ? <LoadState/> : active.isError ? <LoadState error={active.error as Error} onRetry={() => active.refetch()}/> : <Panel title={t('activeSos')} subtitle={language === 'fa' ? 'تازه‌سازی هر ۳۰ ثانیه؛ نه real-time' : 'Refreshes every 30 seconds; not real time'}>{list.length ? <div className="sos-list">{list.map(s => <SosCard key={s.id} item={s} onAction={verb => action.mutate({ id: s.id, verb })}/>)}</div> : <EmptyState>{t('noActiveSos')}</EmptyState>}</Panel>}
    <Panel title={language === 'fa' ? 'تاریخچهٔ درخواست‌ها' : 'Request history'}>{history.isLoading ? <LoadState/> : history.isError ? <LoadState error={history.error as Error} onRetry={() => history.refetch()}/> : history.data?.length ? <div className="event-list">{history.data.map(s => <div className="event-row" key={s.id}><span className="event-dot"/><div><strong>{s.deviceName} · {s.status}</strong><small>{s.trackingStatus} · {s.trackingReason || ''}</small></div><time>{formatDate(s.activatedAt, language)}</time></div>)}</div> : <EmptyState>{t('empty')}</EmptyState>}</Panel>
    {action.isError && <p role="alert" className="form-error">{(action.error as Error).message}</p>}<div className="note-box"><Icon name="heart"/><p>{t('privacyNoThirdParty')} {t('emergencyServices')}</p></div>
  </>;
}
function SosCard({ item, onAction }: { item: Sos; onAction: (verb: 'acknowledge' | 'resolve') => void }) { const { t, language } = useUi(); const canAck = item.status === 'ACTIVE'; const canResolve = ['ACTIVE', 'ACKNOWLEDGED'].includes(item.status); return <article className="sos-card"><div className="sos-card-head"><span className="sos-icon"><Icon name="heart"/></span><div><span className="eyebrow">{item.deviceName}</span><h3>{item.status}</h3><small>{formatDate(item.activatedAt, language)}</small></div><Pill tone={canResolve ? 'bad' : 'neutral'}>{item.trackingStatus}</Pill></div><div className="sos-detail-grid"><Coordinate label={t('battery')} value={item.batteryLevel == null ? '—' : `${item.batteryLevel}%`}/><Coordinate label={language === 'fa' ? 'شبکه' : 'Network'} value={item.networkState}/><Coordinate label={language === 'fa' ? 'مجوز مکان' : 'Location permission'} value={item.permissionStatus}/>{item.latestLocation && <Coordinate label={t('coordinates')} value={`${item.latestLocation.latitude.toFixed(5)}, ${item.latestLocation.longitude.toFixed(5)}`}/>}</div>{item.latestLocation && <p className="micro-note">{formatDate(item.latestLocation.timestamp, language)} · {item.latestLocation.accuracyM == null ? '—' : `±${Math.round(item.latestLocation.accuracyM)}m`} · {item.latestLocation.source}</p>}<div className="sos-actions">{canAck && <button className="btn btn-quiet" onClick={() => onAction('acknowledge')}>{t('acknowledge')}</button>}{canResolve && <button className="btn btn-primary" onClick={() => { if (window.confirm(language === 'fa' ? 'درخواست کمک به‌عنوان حل‌شده ثبت شود؟' : 'Mark this request resolved?')) onAction('resolve'); }}>{t('resolve')}</button>}</div></article>; }
function SosCompact({ item }: { item: Sos }) { const { language } = useUi(); return <div className="sos-compact"><span className="severity-mark critical"><Icon name="heart" size={17}/></span><div><strong>{item.deviceName} · {item.status}</strong><small>{formatDate(item.activatedAt, language)}</small></div><Pill tone="bad">SOS</Pill></div>; }

function ReportsPage() {
  const { t, language } = useUi(); const { devices } = useFamily(); const request = useApi(); const [deviceId, setDeviceId] = useState(''); const [date, setDate] = useState(localDateInput());
  const chosen = deviceId || devices.data?.[0]?.id || '';
  const report = useQuery({ queryKey: ['daily-report', chosen, date], queryFn: () => request<{ date: string; totalMinutes: number; mostUsedApp: { appName: string; usageMinutes: number } | null; appsUsed: number; sessions: number; categories: { category: string; minutes: number }[] }>(`${dpath(chosen, 'usage/report/daily')}?date=${encodeURIComponent(date)}`), enabled: !!chosen });
  return <><PageHeading eyebrow={t('reports')} title={t('reports')} description={language === 'fa' ? 'گزارش روزانهٔ واقعی از usage/report/daily' : 'A real daily report from usage/report/daily'}/><div className="filter-row"><label className="filter-label">{t('childDevice')}<select value={chosen} onChange={e => setDeviceId(e.target.value)}>{devices.data?.map(d => <option key={d.id} value={d.id}>{d.deviceName}</option>)}</select></label><label className="filter-label">{t('today')}<input type="date" value={date} onChange={e => setDate(e.target.value)}/></label></div>
    {devices.isLoading || report.isLoading ? <LoadState/> : !chosen ? <Panel title={t('reports')}><EmptyState>{t('noDevices')}</EmptyState></Panel> : report.isError ? <LoadState error={report.error as Error} onRetry={() => report.refetch()}/> : <><div className="stats-grid three-stats"><StatCard label={t('total')} value={duration(report.data!.totalMinutes, language)} note={report.data!.date} icon="clock"/><StatCard label={language === 'fa' ? 'اپ‌های استفاده‌شده' : 'Apps used'} value={report.data!.appsUsed} note={language === 'fa' ? 'طبق دادهٔ همگام‌شده' : 'From synced data'} icon="devices" accent="mint"/><StatCard label={language === 'fa' ? 'نشست‌ها' : 'Sessions'} value={report.data!.sessions} note={report.data!.mostUsedApp?.appName || t('empty')} icon="chart" accent="amber"/></div><Panel title={language === 'fa' ? 'دسته‌بندی مصرف' : 'Usage categories'}>{report.data!.categories.length ? <div className="app-usage-list">{report.data!.categories.map(c => <div className="usage-row" key={c.category}><div><strong>{c.category}</strong></div><div className="usage-bar"><i style={{ width: `${Math.max(2, Math.min(100, c.minutes / Math.max(1, report.data!.totalMinutes) * 100))}%` }}/></div><b>{duration(c.minutes, language)}</b></div>)}</div> : <EmptyState>{t('empty')}</EmptyState>}</Panel></>}
    <div className="note-box"><Icon name="alert"/><p>{t('unsupportedReports')}</p></div>
  </>;
}

function PrivacyPage() {
  const { t, language } = useUi(); const fa = language === 'fa';
  return <><PageHeading eyebrow={t('privacy')} title={fa ? 'مرکز حریم خصوصی' : 'Privacy Center'} description={fa ? 'شرح شفاف داده‌ها و کنترل‌های واقعاً موجود در API' : 'A transparent view of data and controls actually exposed by the API'}/>
    <div className="privacy-grid">
      <Panel title={fa ? 'چه داده‌ای و برای چه هدفی' : 'Data collected and purpose'}><div className="privacy-list">
        <PrivacyItem icon="lock" title={fa ? 'حساب و نشست' : 'Account and sessions'} text={fa ? 'ایمیل و هش گذرواژه برای احراز هویت؛ refresh token به‌صورت hash در پایگاه‌داده نگهداری می‌شود.' : 'Email and password hash support authentication; refresh tokens are stored as hashes.'}/>
        <PrivacyItem icon="devices" title={fa ? 'دستگاه و وضعیت' : 'Device and status'} text={fa ? 'شناسه، نام، سازنده/مدل، نسخه Android و برنامه، باتری، اتصال، آخرین حضور و وضعیت مجوزها برای pairing و سلامت دستگاه.' : 'Identifiers, name, manufacturer/model, Android/app version, battery, connectivity, last seen and permission status support pairing and device health.'}/>
        <PrivacyItem icon="chart" title={fa ? 'مصرف برنامه و زمان صفحه' : 'App usage and screen time'} text={fa ? 'نام بسته و خلاصه مصرف روزانه برای گزارش و قواعد؛ دسترسی Usage Access تابع مجوز Android است.' : 'Package names and daily summaries support reports and limits; Android Usage Access permission applies.'}/>
        <PrivacyItem icon="pin" title={fa ? 'موقعیت و محدوده امن' : 'Location and geofences'} text={fa ? 'مختصات، دقت، زمان و منبع برای موقعیت/تاریخچه و محدوده امن؛ تابع اشتراک فعال و مجوزهای Android است.' : 'Coordinates, accuracy, time and source support location/history and geofences, subject to sharing settings and Android permissions.'}/>
        <PrivacyItem icon="heart" title={fa ? 'SOS و اعلان‌ها' : 'SOS and notifications'} text={fa ? 'وضعیت نشست اضطراری، رخدادها و در صورت وجود نقاط مکانی همان نشست؛ اعلان‌ها از رخدادهای قابل اقدام ساخته می‌شوند.' : 'Emergency session state, events and any SOS-session locations; notifications are projected from actionable events.'}/>
        <PrivacyItem icon="shield" title={fa ? 'ایمنی وب' : 'Web safety'} text={fa ? 'قواعد و وضعیت/خطای قابلیت ذخیره می‌شود؛ طرح فعلی تاریخچه سایت‌های مرورشده را ذخیره نمی‌کند.' : 'Rules and capability/error status are stored; the current schema does not store visited-site history.'}/>
      </div></Panel>
      <Panel title={fa ? 'نگهداری و کنترل‌های موجود' : 'Retention and available controls'}><div className="privacy-list">
        <PrivacyItem icon="pin" title={fa ? 'تاریخچه موقعیت' : 'Location history'} text={fa ? 'تنظیم هر دستگاه: صفر برای فقط آخرین نقطه یا ۱ تا ۳۶۵ روز؛ API حذف تاریخچه دارد. پاک‌سازی خودکار تنبل است و job سراسری زمان‌بندی‌شده تأیید نشده.' : 'Per-device setting: zero for latest point only or 1–365 days; a history-delete API exists. Purge is lazy; no global scheduled job is verified.'}/>
        <PrivacyItem icon="alert" title={fa ? 'داده‌های دیگر' : 'Other records'} text={fa ? 'برای مصرف روزانه، اعلان، SOS و audit/event retention سراسری قابل‌تنظیم یا حذف خانوادگی در API فعلی تأیید نشده است.' : 'Global configurable retention or family-wide deletion for usage, notifications, SOS and audit/events is not exposed by the current API.'}/>
        <PrivacyItem icon="devices" title={fa ? 'حذف دستگاه' : 'Device removal'} text={fa ? 'حذف دستگاه در API آن را removed می‌کند و نشست‌ها را لغو می‌کند؛ به معنی پاک‌شدن تاریخچه‌های وابسته نیست.' : 'Device removal marks it removed and revokes sessions; it does not mean all associated history is erased.'}/>
      </div></Panel>
      <Panel title={fa ? 'Child، مجوزها و شفافیت عملیاتی' : 'Child, permissions and operational transparency'}><div className="privacy-list">
        <PrivacyItem icon="lock" title={fa ? 'عملکرد Child' : 'Child app'} text={fa ? 'برای sync از شبکه استفاده می‌کند و قابلیت‌های اختیاری به مجوزهای رسمی Android وابسته‌اند. وضعیت محدود/ناموجود نباید به‌عنوان موفق گزارش شود.' : 'Uses the network for sync; optional capabilities depend on official Android permissions. Limited/unavailable states are not represented as success.'}/>
        <PrivacyItem icon="alert" title={fa ? 'قابلیت‌های پشتیبانی‌نشده' : 'Unsupported data'} text={fa ? 'تماس‌ها، مخاطبان، دوربین، میکروفون، عکس‌ها، clipboard و محتوای پیام‌ها در API این پروژه ارائه نشده‌اند.' : 'Call logs, contacts, camera, microphone, photos, clipboard and message contents are not exposed by this project API.'}/>
        <PrivacyItem icon="shield" title={fa ? 'پایش عملیاتی' : 'Operational monitoring'} text={fa ? 'Backend برای سلامت سرویس، شمارنده‌ها و خطاهای redacted ثبت می‌کند. پایش پنهان اضافه نشده است؛ log نباید token، گذرواژه یا مختصات خام داشته باشد.' : 'The backend records service health, counters and redacted errors. No hidden monitoring is added; logs must not contain tokens, passwords or raw coordinates.'}/>
      </div></Panel>
      <Panel title={fa ? 'Export و حذف حساب' : 'Export and account deletion'}><div className="privacy-list">
        <PrivacyItem icon="alert" title={fa ? 'در حال حاضر در دسترس نیست' : 'Not currently available'} text={fa ? 'Export یکپارچه خانواده و حذف حساب/خانواده در Backend API فعلی پیاده‌سازی نشده‌اند. این پنل درخواست را ارسال نمی‌کند و ادعای انجام/حذف نمی‌کند.' : 'Family-wide export and account/family deletion are not implemented by the current backend API. This panel submits no request and does not claim completion.'}/>
        <PrivacyItem icon="shield" title={fa ? 'تفکیک دسترسی' : 'Authorization boundary'} text={fa ? 'هر دسترسی داده باید در Backend با مالکیت خانواده/دستگاه کنترل شود؛ محدودیت UI به‌تنهایی مجوز نیست.' : 'Backend must enforce family/device ownership for data access; UI restrictions are not authorization.'}/>
      </div></Panel>
    </div>
    <div className="note-box"><Icon name="lock"/><p>{fa ? 'توکن‌های Web فقط در حافظه زبانه نگهداری می‌شوند، در localStorage/sessionStorage ذخیره نمی‌شوند و با reload پاک می‌شوند. ترجیح زبان و پوسته در localStorage می‌ماند.' : 'Web tokens stay in tab memory and are cleared on reload; UI language and theme preferences are stored in localStorage.'}</p></div>
  </>;
}
function PrivacyItem({ icon, title, text }: { icon: string; title: string; text: string }) { return <div className="privacy-item"><span><Icon name={icon}/></span><div><strong>{title}</strong><p>{text}</p></div></div>; }

type NotificationPrefs = { enabledCategories: string; quietHoursEnabled: boolean; quietStart: string; quietEnd: string; timezone: string; criticalDuringQuietHours: boolean; dailySummaryEnabled: boolean; cooldownMinutes: number };
function SettingsPage() {
  const { t, language } = useUi(); const request = useApi(); const { family } = useFamily();
  const familySettings = useQuery({ queryKey: ['family-settings'], queryFn: () => request<Record<string, unknown>>('/v1/families/me/settings') });
  const notifications = useQuery({ queryKey: ['notification-preferences'], queryFn: () => request<NotificationPrefs>(`${routes.notifications}/preferences`) });
  return <><PageHeading eyebrow={t('settings')} title={t('settings')} description={language === 'fa' ? 'تنظیمات خوانده‌شده از backend مشترک' : 'Settings read from the shared backend'}/><div className="settings-grid"><Panel title={t('family')} subtitle={family.data?.family.name || '—'}>{family.isLoading ? <LoadState/> : family.isError ? <LoadState error={family.error as Error} onRetry={() => family.refetch()}/> : <div className="setting-list">{familySettings.isLoading ? <LoadState/> : familySettings.isError ? <LoadState error={familySettings.error as Error} onRetry={() => familySettings.refetch()}/> : Object.entries(familySettings.data || {}).map(([key, value]) => <div className="setting-row" key={key}><span>{key}</span><strong>{String(value)}</strong></div>)}</div>}</Panel><Panel title={t('preferences')} subtitle={language === 'fa' ? 'ترجیحات اعلان خانواده' : 'Family notification preferences'}>{notifications.isLoading ? <LoadState/> : notifications.isError ? <LoadState error={notifications.error as Error} onRetry={() => notifications.refetch()}/> : <NotificationPrefsEditor initial={notifications.data!}/>}</Panel></div><Panel title={t('account')}><div className="privacy-list"><PrivacyItem icon="lock" title={t('sessionMemory')} text={t('signInAgain')}/><PrivacyItem icon="alert" title={language === 'fa' ? 'عملیات حساب' : 'Account operations'} text={t('unavailableAccount')}/></div></Panel></>;
}
function NotificationPrefsEditor({ initial }: { initial: NotificationPrefs }) {
  const { language, t } = useUi(); const request = useApi(); const qc = useQueryClient(); const [form, setForm] = useState(initial);
  useEffect(() => setForm(initial), [initial]);
  const save = useMutation({ mutationFn: () => request<NotificationPrefs>(`${routes.notifications}/preferences`, { method: 'PUT', body: jsonBody(form) }), onSuccess: value => { setForm(value); qc.invalidateQueries({ queryKey: ['notification-preferences'] }); } });
  const toggle = (key: 'quietHoursEnabled' | 'criticalDuringQuietHours' | 'dailySummaryEnabled', label: string) => <label className="toggle-row"><span>{label}</span><input type="checkbox" checked={form[key]} onChange={e => setForm({ ...form, [key]: e.target.checked })}/></label>;
  return <form className="prefs-form" onSubmit={e => { e.preventDefault(); save.mutate(); }}>
    {toggle('quietHoursEnabled', language === 'fa' ? 'ساعات سکوت' : 'Quiet hours')}
    <div className="prefs-times"><label>{language === 'fa' ? 'شروع' : 'Start'}<input type="time" value={form.quietStart} onChange={e => setForm({ ...form, quietStart: e.target.value })}/></label><label>{language === 'fa' ? 'پایان' : 'End'}<input type="time" value={form.quietEnd} onChange={e => setForm({ ...form, quietEnd: e.target.value })}/></label></div>
    <label className="prefs-field">{language === 'fa' ? 'منطقهٔ زمانی' : 'Timezone'}<input value={form.timezone} onChange={e => setForm({ ...form, timezone: e.target.value })} placeholder="Europe/Paris" dir="ltr" required/></label>
    {toggle('criticalDuringQuietHours', language === 'fa' ? 'عبور اعلان بحرانی از ساعات سکوت' : 'Allow critical alerts during quiet hours')}
    {toggle('dailySummaryEnabled', language === 'fa' ? 'خلاصهٔ روزانه' : 'Daily summary')}
    <label className="prefs-field">{language === 'fa' ? 'فاصلهٔ تکرار (دقیقه)' : 'Cooldown (minutes)'}<input type="number" min="0" max="240" value={form.cooldownMinutes} onChange={e => setForm({ ...form, cooldownMinutes: Number(e.target.value) })}/></label>
    <button className="btn btn-primary" disabled={save.isPending}>{save.isPending ? '…' : t('save')}</button>{save.isError && <p role="alert" className="form-error">{(save.error as Error).message}</p>}{save.isSuccess && <p role="status" className="success-note">{language === 'fa' ? 'ترجیحات ذخیره شد.' : 'Preferences saved.'}</p>}
  </form>;
}

export default AppRoot;
